		// Token: 0x040005BE RID: 1470
		internal const string QS_TEST_ACCOMMODATIONS = "DECLARE @lucid int = COALESCE((SELECT TOP 1 lucourseid FROM appointmentcourses WHERE appointmentid=@appid),0)\r\nSELECT\tDISTINCT @lucid AS lucourseid,at.personid,dbo.AccommodationsCourseOrTemplate(at.personid,@lucid) AS courseortemplate\r\nINTO #t1\r\nFROM accommodationstest at \r\nWHERE at.AppointmentId=@appid\r\n\r\nSELECT  DISTINCT   ac.lucourseid,m.personid, m.appointmentid, m.ControlID, dc.controlcaption, \r\nCASE \tWHEN (dc.controlcode=520 AND (dc.setting3=0 OR dc.setting3=2))\r\n\t\t\t\tTHEN (SELECT lookuptext FROM lookuplists WHERE lookuplistid=(m.valint / power(2,(SELECT COUNT(orderid) FROM splitstrings2(dc.controlcaption,'.'))))-1)\r\n\tWHEN ((dc.controlcode=3 OR dc.controlcode=703 OR dc.controlcode=520) AND dc.setting3=0)\r\n\t\tTHEN (SELECT ll.lookuptext FROM lookuplists ll WHERE lookuplistid=m.valint)\r\n\tWHEN (((dc.controlcode=1 OR dc.controlcode=701) AND dc.setting3=1) OR ((dc.controlcode=3 OR dc.controlcode=703 OR dc.controlcode=520) AND dc.setting3=-1))\r\n\t\tTHEN (NULL)\r\n\tWHEN (((dc.controlcode=1 OR dc.controlcode=701) AND dc.setting3=0) OR ((dc.controlcode=3 OR dc.controlcode=703 OR dc.controlcode=520) AND dc.setting3=1))\r\n\t\tTHEN (SELECT CAST(m.valbytes AS varchar(8000)))\r\n\tWHEN (dc.controlcode=2 OR dc.controlcode=4)\r\n\t\tTHEN ('True')\r\n\tWHEN ((dc.controlcode=6 OR dc.controlcode=702))\r\n\t\tTHEN (SELECT CAST(m.valdate AS varchar(8000)))\r\n\tWHEN (dc.controlcode=14 AND dc.setting4=1) -- radiogroup\r\n\t\tTHEN (SELECT controlcaption FROM dynamiccontrols WHERE controlid=m.valint)\r\n\tWHEN (dc.controlcode = 14) THEN\r\n                          (SELECT     ll.lookuptext\r\n                            FROM          lookuplists ll\r\n                            WHERE      lookuplistid = m.valint)\r\n\tELSE\r\n\t\t(NULL)\r\n\tEND AS valtext,\r\nm.valint, \r\nm.valbytes, \r\nm.valdate, \r\nm.valimage,\r\ndc.setting1,dc.setting2,dc.setting3,dc.setting4,dc.defaultvalue,dc.controlcode,\r\nCASE WHEN (((dc.controlcode=1 OR dc.controlcode=701) AND dc.setting3=1) OR ((dc.controlcode=3 OR dc.controlcode=703 OR dc.controlcode=520) AND dc.setting3=-1)) THEN 1\r\nELSE 0 END AS valbytesisencrypted\r\n,ad.[offline],ad.expirydate,ad.altlongdescription,ad.note,ad.recommendedbutdeclined,ad.rationale\r\n,CAST(NULL AS DateTime) AS sessiondateentered,ad.recommendedbutdeclineddetail\r\n,a.showOnLetter,dc.uniqueid\r\nINTO #accommodationstestdata2\r\nFROM         \r\n(\r\n\tSELECT \tat.personid,at.controlid,at.appointmentid,at.whoselected,at.datemodified,at.valbytes,at.valdate,at.valint,NULL AS valimage\r\n\tFROM \taccommodationstest at\r\n\tWHERE at.appointmentid=@appid\r\n) AS m\r\n\tLEFT JOIN dynamiccontrols dc ON dc.controlid=m.controlid\r\n\tLEFT JOIN appointmentcourses ac ON ac.appointmentid=m.appointmentid\r\n\tLEFT JOIN accommodationdata ad ON ad.personid=m.personid AND ad.courseid=COALESCE((SELECT TOP 1 courseortemplate FROM #t1 WHERE personid=m.personid AND lucourseid=ac.lucourseid),0)\r\n\tLEFT JOIN Accommodations a ON a.ControlID=m.controlid \r\n \r\nSELECT  DISTINCT at.AppointmentId\r\n\t\t,ad2.DataID,at.controlcaption,at.controlcode,at.controlid\r\n\t\t,at.setting1,at.setting2,at.setting3,at.setting4,at.defaultvalue\r\n\t\t,COALESCE(at.valtext,ad2.valtext,'') AS valtext,\r\n\t\tCOALESCE(at.valbytes,ad2.valbytes) AS valbytes,\r\n\t\tCOALESCE(at.valdate,ad2.valdate) AS valdate,\r\n\t\tCOALESCE(at.valint,ad2.valint) AS valint,\r\n\t\tat.valimage,\r\n\t\tCOALESCE(at.valbytesisencrypted,ad2.valbytesisencrypted) AS valbytesisencrypted,\r\n\t\tdc.setting4string,dc.defaultvaluestring,dc.mask,dc.controlgroup,at.lucourseid,at.personid,dsc.ordernum,dc.uniqueid,\r\n\t\tad2.showonletter AS showonletter1,acc.showonemail,acc.showonreport,\r\n        acc.extratime,acc.isalone,acc.needscomputer,acc.needsReaderScribe,acc.availableInAllRooms,acc.isgroup,acc.tapedexams,acc.other,acc.enlarged,\r\n        acc.longdescription,acc.shortcode\r\nFROM\t#accommodationstestdata2 at LEFT JOIN dynamiccontrols dc ON dc.controlid=at.controlid\r\n\t\tLEFT JOIN accommodationdata ad2 ON ad2.PersonID=at.personid \r\n\t\t\tAND ad2.ControlID=at.controlid \r\n\t\t\t--AND ad2.courseid=dbo.AccommodationsCourseOrTemplate(at.personid,at.lucourseid)\r\n\t\t\tAND ad2.courseid=COALESCE((SELECT TOP 1 courseortemplate FROM #t1 WHERE personid=at.personid AND lucourseid=at.lucourseid),0)\r\n        LEFT JOIN dynamicscreencontrols dsc ON dsc.screennum=4 AND dsc.controlid=at.controlid\r\n\t\tLEFT JOIN accommodations acc ON acc.controlID=at.controlid\r\nWHERE\tat.AppointmentId=@appid \r\nORDER BY dsc.ordernum,at.controlcaption\r\n\r\nDROP TABLE #accommodationstestdata2\r\nDROP TABLE #t1";

