		internal const string QS_TEST_BOOKING_MAIL_MERGE_CONTEXTS_BY_DATE = "SELECT DISTINCT a.appointmentid,a.examid,att.personid,ac.lucourseid,a.startdate \r\nFROM    appointments a LEFT JOIN attendees att ON att.appointmentid=a.appointmentid AND att.personid IN (SELECT personid FROM peoplegroups WHERE groupid=1)\r\n        LEFT JOIN appointmentcourses ac ON ac.appointmentid=a.appointmentid\r\nWHERE   a.startdate>=@startdate AND a.startdate<=@enddate\r\n        AND NOT a.examid IS NULL AND a.examid>0\r\n        AND (@showcancelled=1 OR a.cancelled=0)\r\n        AND (@excludeapptypeids='' OR a.apptypeid IN (SELECT orderid AS apptypeid FROM splitorderids(@excludeapptypeids,',')))\r\nORDER BY a.startdate";

