r\n        lucd.altlookupstring AS examcoursesubject,luc.course AS examcoursecourse,luc.[section] AS examcoursesection,luc.timeofday AS examcoursetimeofday,\r\n        lucs.startdate AS studentcoursestartdate,lucs.enddate AS studentcourseenddate,lucs.duration AS studentcourseduration,lucs.term AS studentcourseterm,\r\n        lucs.subjectid AS studentcoursesubjectid,lucds.altlookupstring AS studentcoursesubject,lucs.course AS studentcoursecourse,\r\n        lucs.[section] AS studentcoursesection,lucs.timeofday AS studentcoursetimeofday,\r\n        rm.firstname AS roomfirstname,rm.student_no AS roomstudent_no,rm.lastname AS roomlastname,attrm.personid AS roompersonid,a.totalbreakminutes AS breaktimeminutes\r\nFROM\tapps a LEFT JOIN AppointmentTypes at ON at.apptypeid=a.AppTypeID \r\n\t\tLEFT JOIN AppointmentTypeGroups atg ON atg.AppointmentTypeGroupID=at.appointmentTypeGroupID \r\n\t\tLEFT JOIN AppointmentMemos am ON am.AppointmentID=a.AppointmentID \r\n\t\tLEFT JOIN People pwb ON pwb.PersonID=a.whoadded \r\n\t\tLEFT JOIN AppointmentCancelledReason acr ON acr.appointmentid=a.AppointmentID\r\n\t\tLEFT JOIN CancelReason cr ON cr.cancelreasonid=acr.cancelreasonid \r\n\t\tLEFT JOIN People pcb ON pcb.PersonID=acr.cancelledbypersonid \r\n        LEFT JOIN AppointmentShowTimeAs ast ON ast.extraiconid=a.appcode\r\n        LEFT JOIN exams e ON e.examid=a.examid\r\n        LEFT JOIN lucourses luc ON luc.lucourseid=e.lucourseid\r\n        LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n        LEFT JOIN appointmentcourses ac ON ac.appointmentid=a.appointmentid\r\n        LEFT JOIN lucourses lucs ON lucs.lucourseid=ac.lucourseid\r\n        LEFT JOIN lucoursedata lucds ON lucds.lucoursedataid=lucs.subjectid\r\n        LEFT JOIN attendees attrm ON attrm.appointmentid=a.appointmentid AND attrm.personid IN (SELECT personid FROM peoplegroups WHERE groupid=3)\r\n        LEFT JOIN people rm ON rm.personid=attrm.personid\r\n        LEFT JOIN peoplegroups pg ON pg.groupid<=10 AND pg.personid=a.personid\r\n";

