		internal const string QS_TESTS_BY_STUDENT = "SELECT\ta.appointmentid,a.AppTypeID,a.[description] AS apptypedescription,a.subject AS subtitle,\r\n        at.appointmenttypegroupid,atg.title AS apptypegrouptitle,\r\n\t\ta.appCode,a.startDate,a.endDate,a.[subject],a.location,\r\n\t\ta.cancelled,a.isLocked,a.isHidden,a.groupCode,a.extraattendeescount,\r\n\t\ta.AttendeeID,a.PersonID,a.firstName,a.lastName,a.student_no,a.miscCode,a.noShow,pg.groupid,\r\n\t\tat.isCourse,at.isWorkshop,at.defaultColour,\r\n\t\tam.memoText,am.isEncrypted,\r\n\t\ta.whoadded AS wbpersonid,pwb.firstName AS wbfirstname,pwb.lastName AS wblastname,pwb.student_no AS wbstudent_no,\r\n\t\ta.dateAdded AS datebooked,a.overrideColour,a.actualstarttime,a.actualendtime,\r\n\t\tacr.cancelreasonid,cr.cancelreasongroupname,cr.cancelreasontitle,\r\n\t\tacr.cancelledbypersonid AS cbpersonid,pcb.firstName AS cbfirstname,pcb.lastName AS cblastname,pcb.student_no AS cbstudent_no,\r\n\t\tacr.cancelleddate,acr.cancelreasontext,\r\n\t\tast.appointmentshowtimeasid,ast.showtimeastitle,ast.extraiconid,ast.showtimeascolour,\r\n        a.examid,e.dateentered,e.lucourseid AS examcourselucourseid,e.description,e.dateoftest,e.visible,e.usercomment,e.testduration,e.lastmodified,e.wholastmodified,\r\n        e.typecode,e.extendedproperties,e.testpickedupdate,e.testpickedupnote,e.instructorcontacteddate,e.instructorcontactednote,e.privatenote,\r\n        e.instructoracknowledged,e.filename,\r\n        ac.appointmentcourseid,ac.lucourseid AS studentcourselucourseid,ac.originalstartdatetime,ac.originalenddatetime,ac.testnote,ac.studentnote,ac.instructoracknowledgevalue,ac.instructoracknowledgedate,\r\n        ac.privatenote2,ac.testpickedupdate AS stestpickedupdate,ac.testpickedupnote AS stestpickedupnote,ac.extendedproperties AS sextendedproperties,\r\n        luc.startdate AS examcoursestartdate,luc.enddate AS examcourseenddate,luc.duration AS examcourseduration,luc.term AS examcourseterm,luc.subjectid AS examcoursesubjectid,\r\n        lucd.altlookupstring AS examcoursesubject,luc.course AS examcoursecourse,luc.[section] AS examcoursesection,luc.timeofday AS examcoursetimeofday,\r\n        lucs.startdate AS studentcoursestartdate,lucs.enddate AS studentcourseenddate,lucs.duration AS studentcourseduration,lucs.term AS studentcourseterm,\r\n        lucs.subjectid AS studentcoursesubjectid,lucds.altlookupstring AS studentcoursesubject,lucs.course AS studentcoursecourse,\r\n        lucs.[section] AS studentcoursesection,lucs.timeofday AS studentcoursetimeofday,\r\n        rm.firstname AS roomfirstname,rm.student_no AS roomstudent_no,rm.lastname AS roomlastname,attrm.personid AS roompersonid,a.totalbreakminutes AS breaktimeminutes\r\nFROM\tapps a LEFT JOIN AppointmentTypes at ON at.apptypeid=a.AppTypeID \r\n\t\tLEFT JOIN AppointmentTypeGroups atg ON atg.AppointmentTypeGroupID=at.appointmentTypeGroupID \r\n\t\tLEFT JOIN AppointmentMemos am ON am.AppointmentID=a.AppointmentID \r\n\t\tLEFT JOIN People pwb ON pwb.PersonID=a.whoadded \r\n\t\tLEFT JOIN AppointmentCancelledReason acr ON acr.appointmentid=a.AppointmentID\r\n\t\tLEFT JOIN CancelReason cr ON cr.cancelreasonid=acr.cancelreasonid \r\n\t\tLEFT JOIN People pcb ON pcb.PersonID=acr.cancelledbypersonid \r\n        LEFT JOIN AppointmentShowTimeAs ast ON ast.extraiconid=a.appcode\r\n        LEFT JOIN exams e ON e.examid=a.examid\r\n        LEFT JOIN lucourses luc ON luc.lucourseid=e.lucourseid\r\n        LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n        LEFT JOIN appointmentcourses ac ON ac.appointmentid=a.appointmentid\r\n        LEFT JOIN lucourses lucs ON lucs.lucourseid=ac.lucourseid\r\n        LEFT JOIN lucoursedata lucds ON lucds.lucoursedataid=lucs.subjectid\r\n        LEFT JOIN attendees attrm ON attrm.appointmentid=a.appointmentid AND attrm.personid IN (SELECT personid FROM peoplegroups WHERE groupid=3)\r\n        LEFT JOIN people rm ON rm.personid=attrm.personid\r\n        LEFT JOIN peoplegroups pg ON pg.groupid<=10 AND pg.personid=a.personid\r\nWHERE (NOT a.examid IS NULL OR a.apptypeid IN (SELECT apptypeid FROM appointmenttypes WHERE iscourse=1))\r\n        AND a.startdate BETWEEN @startdate AND @enddate\r\n        AND (@hidecancelled=0 OR a.cancelled=0)\r\n        AND a.personid=@pid\r\nORDER BY a.appointmentid,pg.groupid,a.AttendeeID";

