        lucd.altlookupstring AS examcoursesubject,luc.course AS examcoursecourse,luc.[section] AS examcoursesection,luc.timeofday AS examcoursetimeofday,\r\n        lucs.startdate AS studentcoursestartdate,lucs.enddate AS studentcourseenddate,lucs.duration AS studentcourseduration,lucs.term AS studentcourseterm,\r\n        lucs.subjectid AS studentcoursesubjectid,lucds.altlookupstring AS studentcoursesubject,lucs.course AS studentcoursecourse,\r\n        lucs.[section] AS studentcoursesection,lucs.timeofday AS studentcoursetimeofday,\r\n        rm.firstname AS roomfirstname,rm.student_no AS roomstudent_no,rm.lastname AS roomlastname,attrm.personid AS roompersonid,a.totalbreakminutes AS breaktimeminutes\r\nFROM\tapps a LEFT JOIN AppointmentTypes at ON at.apptypeid=a.AppTypeID \r\n\t\tLEFT JOIN AppointmentTypeGroups atg ON atg.AppointmentTypeGroupID=at.appointmentTypeGroupID \r\n\t\tLEFT JOIN AppointmentMemos am ON am.AppointmentID=a.AppointmentID \r\n\t\tLEFT JOIN People pwb ON pwb.PersonID=a.whoadded \r\n\t\tLEFT JOIN AppointmentCancelledReason acr ON acr.appointmentid=a.AppointmentID\r\n\t\tLEFT JOIN CancelReason cr ON cr.cancelreasonid=acr.cancelreasonid \r\n\t\tLEFT JOIN People pcb ON pcb.PersonID=acr.cancelledbypersonid \r\n        LEFT JOIN AppointmentShowTimeAs ast ON ast.extraiconid=a.appcode\r\n        LEFT JOIN exams e ON e.examid=a.examid\r\n        LEFT JOIN lucourses luc ON luc.lucourseid=e.lucourseid\r\n        LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n        LEFT JOIN appointmentcourses ac ON ac.appointmentid=a.appointmentid\r\n        LEFT JOIN lucourses lucs ON lucs.lucourseid=ac.lucourseid\r\n        LEFT JOIN lucoursedata lucds ON lucds.lucoursedataid=lucs.subjectid\r\n        LEFT JOIN attendees attrm ON attrm.appointmentid=a.appointmentid AND attrm.personid IN (SELECT personid FROM peoplegroups WHERE groupid=3)\r\n        LEFT JOIN people rm ON rm.personid=attrm.personid\r\n        LEFT JOIN peoplegroups pg ON pg.groupid<=10 AND pg.personid=a.personid\r\nWHERE a.appointmentid IN (SELECT orderid AS appointmentid FROM splitorderids(@appointmentids,','))\r\nORDER BY a.appointmentid,pg.groupid,a.attendeeid";

		// Token: 0x040005C9 RID: 1481
		internal const string QI_TESTFOREDIT_BOOKINGSPECIFIC = "IF NOT EXISTS(SELECT appointmentcourseid FROM appointmentcourses WHERE appointmentid=@appid)\r\nBEGIN\r\n    DECLARE @id0 int\r\n    SET @id0=CASE WHEN @examstatuslookupid IS NULL THEN NULL ELSE (SELECT TOP 1 examstatuslookupid FROM examstatuslookup WHERE examstatuslookupid=@examstatuslookupid) END;\r\n\r\n    INSERT INTO appointmentcourses (appointmentid,lucourseid,originalstartdatetime,originalenddatetime,testnote,studentnote,instructoracknowledgevalue,instructoracknowledgedate,privatenote2,\r\n            testpickedupdate,testpickedupnote,examstatuslookupid)\r\n    VALUES (@appid,@lucourseid,@originalstartdatetime,@originalenddatetime,@testnote,@studentnote,@instructoracknowledgevalue,@instructoracknowledgedate,@privatenote2,\r\n            @testpickedupdate,@testpickedupnote,@id0)\r\n    \r\n    SELECT CAST(SCOPE_IDENTITY() AS int) AS appointmentcourseid\r\nEND\r\nELSE \r\nBEGIN\r\nDECLARE @id int\r\nSET @id=CASE WHEN NOT @examstatuslookupid IS NULL THEN @examstatuslookupid ELSE (SELECT TOP 1 examstatuslookupid FROM appointmentcourses WHERE appointmentid=@appid) END;\r\n\r\nUPDATE appointmentcourses SET \r\n    originalstartdatetime=CASE WHEN @updateoriginaldatetime=1 THEN @originalstartdatetime ELSE originalstartdatetime END,\r\n    originalenddatetime=CASE WHEN @updateoriginaldatetime=1 THEN @originalenddatetime ELSE originalenddatetime END,\r\n    testnote=@testnote,studentnote=@studentnote,\r\n    instructoracknowledgevalue=@instructoracknowledgevalue,instructoracknowledgedate=@instructoracknowledgedate,privatenote2=@privatenote2,\r\n    testpickedupdate=@testpickedupdate,testpickedupnote=@testpickedupnote,examstatuslookupid=@id\r\nWHERE appointmentid=@appid\r\nSELECT appointmentcourseid FROM appointmentcourses WHERE appointmentid=@appid\r\nEND";

		// Token: 0x040005CA RID: 1482
		internal const string QI_TEST_ACCOMMODATIONS = "DECLARE @examid int, @lucid int\r\nSET @examid = (SELECT TOP 1 examid FROM appointments WHERE appointmentid=@appid)\r\n\r\nIF NOT @examid IS NULL AND NOT EXISTS(SELECT examid FROM accommodationstest WHERE examid=@examid AND appointmentid=@appid AND personid=@pid AND controlid=@cid)\r\nBEGIN\r\n    SET @lucid = (SELECT TOP 1 lucourseid FROM exams WHERE examid=@examid )\r\n\r\n    DECLARE @courseortemplate int = (SELECT dbo.AccommodationsCourseOrTemplate(@pid,@lucid))\r\n\r\n    SELECT valbytes,valint,valdate INTO #t1 FROM accommodationdata WHERE personid=@pid AND controlid=@cid AND courseid=COALESCE(@courseortemplate,0) ORDER BY courseid;\r\n    DECLARE @valbytes varbinary(8000);\r\n    DECLARE @valint int;\r\n    DECLARE @valdate datetime;\r\n    SET @valbytes=(SELECT TOP 1 valbytes FROM #t1);\r\n    SET @valint=(SELECT TOP 1 valint FROM #t1);\r\n    SET @valdate=(SELECT TOP 1 valdate FROM #t1);\r\n\r\n    INSERT INTO accommodationstest (examid,personid,controlid,whoselected,datemodified,appointmentid,valbytes,valint,valdate)\r\n        VALUES (@appid,@pid,@cid,@whoami,getdate(),@appid,@valbytes,@valint,@valdate);\r\n\r\n    DROP TABLE #t1\r\nEND";

		// Token: 0x040005CB RID: 1483
		internal const string QD_TEST_ACCOMMODATIONS = "DECLARE @examid int\r\nSET @examid = (SELECT TOP 1 COALESCE(examid,@appid) AS examid FROM appointments WHERE appointmentid=@appid) \r\n    DELETE FROM accommodationstest \r\n        WHERE   (examid=@examid OR examid=@appid) AND appointmentid=@appid AND personid=@pid \r\n                AND controlid IN (SELECT orderid AS controlid FROM splitorderids(@cids,','))";

