		internal const string QU_INSERT_OR_UPDATE_OR_DELETE_APPOINTMENT_COURSE_INFO = "IF @lucid IS NULL OR @lucid<1\r\nBEGIN\r\n    DELETE FROM appointmentcourses WHERE appointmentid=@appid\r\n    SET @appointmentcourseid=0\r\nEND\r\nELSE\r\nBEGIN\r\n    IF EXISTS(SELECT appointmentcourseid FROM appointmentcourses WHERE appointmentid=@appid)\r\n        UPDATE appointmentcourses SET lucourseid=@lucid,originalstartdatetime=@originalstartdatetime,originalenddatetime=@originalenddatetime,testnote=@testnote,studentnote=@studentnote \r\n        WHERE appointmentid=@appid\r\n    ELSE \r\n        INSERT INTO appointmentcourses (appointmentid,lucourseid,originalstartdatetime,originalenddatetime,testnote,studentnote)\r\n        VALUES (@appid,@lucid,@originalstartdatetime,@originalenddatetime,@testnote,@studentnote)\r\n\r\n    SET @appointmentcourseid=(SELECT TOP 1 appointmentcourseid FROM appointmentcourses WHERE appointmentid=@appid)\r\nEND";

		// Token: 0x040005D1 RID: 1489
		internal const string QU_INSERT_OR_UPDATE_OR_DELETE_APPOINTMENT_COURSE_INFO2 = "DECLARE @classStart DATETIME, @classEnd DATETIME\r\nDECLARE @lucid int\r\nIF @originalstartdatetime IS NULL OR @originalenddatetime IS NULL\r\nBEGIN\r\n    SET @classStart=(SELECT TOP 1 dateoftest FROM exams WHERE examid=@examid)\r\n    SET @classEnd=(SELECT TOP 1 DATEADD(n,testduration,dateoftest) AS edt FROM exams WHERE examid=@examid)\r\nEND\r\nELSE\r\n    SET @classStart=@originalstartdatetime\r\n    SET @classEnd=@originalenddatetime\r\nBEGIN\r\nEND\r\n\r\nSET @lucid=(SELECT TOP 1 lucourseid FROM exams WHERE examid=@examid)\r\n\r\nIF EXISTS(SELECT appointmentcourseid FROM appointmentcourses WHERE appointmentid=@appid)\r\nBEGIN\r\n    UPDATE appointmentcourses SET originalstartdatetime=@classStart,originalenddatetime=@classEnd,testnote=@testnote,studentnote=@studentnote \r\n    WHERE appointmentid=@appid\r\nEND\r\nELSE \r\n    INSERT INTO appointmentcourses (appointmentid,lucourseid,originalstartdatetime,originalenddatetime,testnote,studentnote)\r\n    VALUES (@appid,@lucid,@classStart,@classEnd,@testnote,@studentnote)\r\n\r\nSET @appointmentcourseid=(SELECT TOP 1 appointmentcourseid FROM appointmentcourses WHERE appointmentid=@appid)";

